from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(group: str) -> int:
        current = 0
        max_d = 0
        for ch in group:
            if ch == '(':
                current += 1
                max_d = max(max_d, current)
            elif ch == ')':
                current -= 1
        return max_d

    return [max_depth(g) for g in paren_string.split()]
